    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    ones=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    sixes=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==6]
    # Connect each adjacent pair of 1 markers by a diagonal segment.
    for i,(r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            if r2!=r1 and abs(r2-r1)==abs(c2-c1):
                dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
                for k in range(1,abs(r2-r1)):
                    r,c=r1+dr*k,c1+dc*k
                    if grid[r][c]==8 or grid[r][c]==4: out[r][c]=1
    # A 6 marks a diagonal ray, extended through the board in its alignment.
    # Determine ray slope from marker alignment where possible; otherwise down-right.
    for r0,c0 in sixes:
        slope=1
        for r1,c1 in sixes:
            if r1!=r0 and c1-c0==r1-r0:
                slope=1; break
            if r1!=r0 and c1-c0==-(r1-r0):
                slope=-1; break
        # Continue along that line in both directions.
        for sign in (-1,1):
            r,c=r0+sign,c0+sign*slope
            while 0<=r<h and 0<=c<w:
                if out[r][c] not in (1,): out[r][c]=6
                r+=sign;c+=sign*slope
    return out
